import { unstable_cache, revalidateTag } from 'next/cache';

// Simulate a slow database fetch
const getProducts = unstable_cache(
  async () => {
    // Simulate network delay to ERP/PIM
    await new Promise((resolve) => setTimeout(resolve, 2000));

    return [
      { id: '101', name: 'Ergonomic Office Chair', price: 249.99, stock: 45 },
      { id: '102', name: 'Wireless Mechanical Keyboard', price: 129.99, stock: 120 },
      { id: '103', name: 'USB-C Docking Station', price: 89.99, stock: 15 },
      { id: '104', name: 'Ultrawide Monitor 34"', price: 499.99, stock: 8 },
      { id: '105', name: 'Noise Cancelling Headphones', price: 199.99, stock: 32 },
    ];
  },
  ['products-key'], 
  { 
    tags: ['products'],
    revalidate: 3600 // Cache for 1 hour by default
  }
);

export default async function AdminCatalogPage() {
  const products = await getProducts();
  const lastRefreshed = new Date().toLocaleTimeString();

  async function syncCatalog() {
    'use server';
    // In a real app, this might trigger a background job to pull from ERP.
    // For now, we simply invalidate the cache so the next request fetches fresh data.
    revalidateTag('products');
  }

  return (
    <div className="p-8 font-sans">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Admin Product Catalog</h1>
        <div className="flex items-center gap-4">
          <span className="text-sm text-gray-500">
            Last updated: {lastRefreshed}
          </span>
          <form action={syncCatalog}>
            <button 
              type="submit"
              className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 transition-colors"
            >
              Sync Latest Catalog
            </button>
          </form>
        </div>
      </div>

      <div className="border rounded-lg overflow-hidden shadow-sm">
        <table className="w-full text-left border-collapse">
          <thead className="bg-gray-50">
            <tr>
              <th className="p-4 border-b font-medium text-gray-600">ID</th>
              <th className="p-4 border-b font-medium text-gray-600">Product Name</th>
              <th className="p-4 border-b font-medium text-gray-600">Price</th>
              <th className="p-4 border-b font-medium text-gray-600">Stock</th>
            </tr>
          </thead>
          <tbody>
            {products.map((product) => (
              <tr key={product.id} className="hover:bg-gray-50">
                <td className="p-4 border-b text-gray-500 font-mono text-sm">{product.id}</td>
                <td className="p-4 border-b font-medium">{product.name}</td>
                <td className="p-4 border-b">${product.price.toFixed(2)}</td>
                <td className="p-4 border-b">
                  <span className={`px-2 py-1 rounded text-xs font-medium ${
                    product.stock < 10 ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'
                  }`}>
                    {product.stock} units
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <p className="mt-4 text-sm text-gray-500 max-w-2xl">
        Note: The catalog is cached for performance. Click "Sync Latest Catalog" to refresh data from the upstream ERP system. 
        Updates may take a moment to reflect.
      </p>
    </div>
  );
}

